import { HOME_INTRO_CRITICAL_CSS, HOME_INTRO_BOOTSTRAP } from './home-intro.js';
import { renderTrajectory } from './trajectory-page.js';
import { renderModuleExperience } from './module-experiences.js';
import { renderFooterWordmark } from './footer-wordmark.js';
import { renderWordmark } from './wordmark.js';
import { renderMedicalExperiences } from './medical-experiences.js';
import { renderJourneyGuide } from './journey-guide.js';
import { renderPrincipleVisual } from './principle-visuals.js';
import { renderScienceSection } from './science-content.js';
import { projects, principles, profiles, editorial, productUrl, siteUrl, imageNotice, directoryProfiles } from './content.js';
import { renderProject, renderCommunity, renderDirectory } from './pages.js';
export const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, s => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const e=escapeHtml;
export const arrow = '<svg viewBox="0 0 30 20" fill="none" aria-hidden="true"><path d="M1 10h26M18 1l9 9-9 9" stroke="currentColor" stroke-width="1.25"/></svg>';
const star='<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><text x="16" y="16" text-anchor="middle" dominant-baseline="central" fill="currentColor" font-family="Roobert,Geist,Arial,sans-serif" font-size="24" font-weight="550" letter-spacing="0" textLength="30" lengthAdjust="spacingAndGlyphs">OS</text></svg>';
export function seal(target='#works',label='Explore a THE MED') {return `<a class="scroll-seal" href="${target}" aria-label="${label}"><svg viewBox="0 0 100 100" aria-hidden="true"><defs><path id="seal-path" d="M50,50 m-36,0 a36,36 0 1,1 72,0 a36,36 0 1,1 -72,0"/></defs><text><textPath href="#seal-path" textLength="225">CONTINUE EXPLORANDO · THE MED · </textPath></text></svg><span>↓</span></a>`;}
export function header(page='home') {const peer=['community','directory'].includes(page);const nav=peer?`<a href="/comunidade/" ${page==='community'?'aria-current="page"':''}>Comunidade</a><a href="/percursos/" ${page==='directory'?'aria-current="page"':''}>Percursos</a>`:`<a href="/#works">Ecossistema</a><a href="/#manifesto">Nossa visão</a><a href="/comunidade/">Comunidade</a><a href="/#contact">Comece por aqui</a>`;return `<a class="skip-link" href="#main">Pular para o conteúdo</a><header class="site-header"><div class="container header-grid"><a class="brand" href="/" aria-label="THE MED | Your Medical Journey — início"><span class="brand-wordmark" aria-hidden="true">${renderWordmark()}</span></a><span class="header-caption" lang="en">Your Medical<br>Journey</span><nav class="desktop-nav" aria-label="Navegação principal">${nav}</nav><button class="menu-toggle" aria-expanded="false" aria-controls="mobile-menu" aria-label="Abrir menu"><span></span><span></span></button></div></header><div class="mobile-menu" id="mobile-menu" hidden><div class="menu-glow"></div><nav aria-label="Menu móvel"><a href="/#works">Ecossistema</a><a href="/#manifesto">Nossa visão</a><a href="/comunidade/">Comunidade</a><a href="/percursos/">Percursos</a><a href="/#contact">Comece por aqui</a></nav><a class="menu-product" href="${productUrl || 'https://innectaos.vercel.app/'}" target="_blank" rel="noopener">Conheça o produto ${arrow}</a><p>Medicina. Pesquisa. Possibilidades.</p></div>`;}
export function footer(){return `<footer id="contact" data-footer><div class="container footer-grid"><div class="footer-main"><h2 class="intro reveal">Seu próximo passo<br>merece um <i>novo olhar.</i> ${arrow}</h2><div class="contact"><span>Uma trajetória inteira de possibilidades.</span><a href="${productUrl || 'https://innectaos.vercel.app/'}" target="_blank" rel="noopener" aria-label="Conheça a the med"><span class="footer-cta-copy">Conheça a ${renderFooterWordmark()}</span> ${arrow}</a></div><div class="footer-topics"><div><h3>Construa com intenção.</h3><p>Do que você faz hoje<br>ao caminho que quer percorrer.</p><a href="/modulos/trajetoria/">Explore sua trajetória ${arrow}</a></div><div><h3>Avance em companhia.</h3><p>Pesquisa, comunidade<br>e orientação conectadas.</p><a href="/comunidade/">Encontre novas perspectivas ${arrow}</a></div></div></div><div class="footer-links"><span>Continue a conversa</span><a href="${productUrl || 'https://innectaos.vercel.app/'}" target="_blank" rel="noopener">Produto ↗</a><a href="${siteUrl || 'https://innecta.vercel.app/'}" target="_blank" rel="noopener">Apresentação ↗</a><a href="/percursos/">Percursos ↗</a><a href="/modulos/mentor/">Mentor + Ultra ↗</a></div><div class="footer-note"><span>THE MED · EM PRÉ-LANÇAMENTO</span><span>Uma experiência para conhecer o que estamos construindo.</span></div></div><div class="footer-closing-symbol"><img src="/assets/the-med-symbol-09-preto.svg" alt="Símbolo the med" width="217" height="236" loading="lazy" decoding="async"></div><button class="back-top" data-back-top aria-label="Voltar ao topo">↑</button></footer>`;}
function card(p,index){return `<li class="project-card reveal" data-scroll data-scroll-speed="${index%2 ? '.4':'0'}"><a href="/modulos/${e(p.slug)}/" class="project-card-content" data-cursor="Explorar"><div class="card-image composition-${index+1}" style="--card-accent:${e(p.accent || '#753947')}"><div class="card-art-number" aria-hidden="true">0${index+1}</div><img src="/${e(p.cover).replace(/^\//,'')}" alt="Interface do módulo ${e(p.title)} da THE MED" width="1400" height="1000" loading="lazy"><span class="card-art-label" aria-hidden="true">${e(p.title)}</span><span class="card-arrow">↗</span></div><div class="card-caption"><h3>${e(p.title)}</h3><span>${e(p.category)}</span></div></a></li>`;}
export function renderHome(){return `<div class="home-world" data-shared-scene><div class="shared-artwork" data-shared-artwork data-render-mode="pending" aria-hidden="true"><div class="hero-fallback" aria-hidden="true"><div class="fallback-field"></div><div class="fallback-lens"></div></div><canvas class="hero-canvas" id="lens-artwork" aria-hidden="true"></canvas></div><section class="hero" id="home"><div class="container hero-inner"><h1 class="hero-sentence"><span class="hero-copy-layer" data-hero-current><span class="hero-line"><span data-hero-prefix>Uma nova forma de</span></span> <span class="hero-line"><i data-hero-word>conectar seu futuro.</i></span></span></h1>${seal()}<p class="hero-caption">Sua vida acadêmica.<br>Um universo de possibilidades.</p></div><div class="intro-greeting" aria-hidden="true"><span>Olá.</span><span>Bem-vindo à <i class="intro-brand-mark">${renderWordmark()}</i></span></div></section>${renderScienceSection()}</div><div class="container home-content"><section id="partners"><span id="works" class="legacy-anchor" aria-hidden="true"></span><h2 class="eyebrow reveal">CONEXÕES QUE FAZEM SUA TRAJETÓRIA AVANÇAR</h2><p class="capability-words reveal">${['Visão','Currículo Studio','Instituições','Comparar','Residência','Internacional','Meu Caminho','Pesquisa','Ligas','Mentor','Acervo','Club'].map(x=>`<span>${x}</span>`).join(' ')}</p><a class="text-link reveal" href="/modulos/trajetoria/">Explore as possibilidades ${arrow}</a></section>${renderMedicalExperiences()}<section id="manifesto"><h2 class="eyebrow reveal">${star} NOSSA VISÃO</h2><p class="manifesto-lines"><span>Não é sobre chegar</span><span>mais <i>rápido.</i></span><span>É sobre construir</span><span>um caminho que</span><span>faça <i>sentido.</i></span></p><span class="manifesto-star" aria-hidden="true">${star}</span></section><section id="strengths">${principles.map((p,i)=>`<section class="principle reveal" id="principle-${['conectar','construir','acompanhar'][i]}"><h3 class="eyebrow">${e(p.title)}</h3><div class="principle-content">${renderPrincipleVisual(i)}<div class="principle-text"><span class="principle-number">0${i+1}</span><p>${e(p.body || p.description || p.text)}</p></div></div></section>`).join('')}</section><div class="marquee" aria-hidden="true"><p data-marquee>Seu futuro é <i>feito de conexões.</i></p></div></div><div class="container"><section class="editorial-cta reveal"><h2 class="eyebrow">${star} CONHECIMENTO QUE CIRCULA</h2><div class="editorial-cta-content"><p>Nenhuma trajetória se constrói sozinha. Aproximamos perguntas, oportunidades e pessoas para transformar o que você aprende em caminhos que pode percorrer.</p><a class="circle-link" href="/comunidade/"><span>Conheça<br>a comunidade</span>${arrow}</a></div></section><section class="tiles tiles--rotated" id="product-mosaic" aria-label="Perspectivas do ecossistema THE MED"><div class="tiles__wrap">${[0,1,2,3].map((r)=>`<div class="tiles__line" data-tile-row="${r}">${[0,1,2].map((c)=>{const p=projects[(r*3+c)%projects.length];return `<div class="tiles__line-img"><img src="/assets/tiles/${e(p.slug)}.png" alt="" loading="lazy" decoding="async" width="2880" height="1800"></div>`}).join('')}</div>`).join('')}</div></section>${renderJourneyGuide({star,arrow})}</div>`;}
export function renderContent(page,slug){if(page==='project')return slug==='trajetoria'?renderTrajectory():renderModuleExperience(slug);if(page==='community')return renderCommunity(editorial,projects);if(page==='directory')return renderDirectory(directoryProfiles);if(page==='404')return `<section class="hero not-found-hero" data-render-mode="pending"><div class="hero-fallback" aria-hidden="true"><div class="fallback-field"></div><div class="fallback-lens"></div></div><canvas class="hero-canvas" aria-hidden="true"></canvas><div class="container not-found"><p class="eyebrow">404 · UM DESVIO NO CAMINHO</p><h1>Vamos encontrar<br>um novo <i>começo.</i></h1><a class="text-link" href="/">Voltar para a THE MED ${arrow}</a></div></section>`;return renderHome();}
export function renderDocument({page='home',slug='',build='dev'}){const p=projects.find(p=>p.slug===slug);if(page==='project'&&!p)return renderDocument({page:'404',build});const title=page==='project'?`${p.title} — the med | Your Medical Journey`:page==='community'?'Comunidade — the med | Your Medical Journey':page==='directory'?'Percursos — the med | Your Medical Journey':page==='404'?'Página não encontrada — the med | Your Medical Journey':'the med | Your Medical Journey';return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${page==='home'?`<style data-home-intro-critical>${HOME_INTRO_CRITICAL_CSS}</style><script data-home-intro-bootstrap>${HOME_INTRO_BOOTSTRAP}</script>`:''}<meta name="theme-color" content="#160e12"><title>${e(title)}</title><meta name="description" content="${e(p?.summary || 'Um ecossistema para conectar sua trajetória acadêmica e médica. Explore planejamento, pesquisa, oportunidades, comunidade e orientação com a THE MED.')}"><meta name="interny-build" content="${e(build)}"><meta property="og:type" content="website"><meta property="og:title" content="${e(title)}"><meta property="og:description" content="Uma nova perspectiva para sua trajetória acadêmica e médica. THE MED, em pré-lançamento."><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg?v=symbol09-small-20261024"><link rel="preload" as="font" href="/assets/Roobert-Regular.woff2" type="font/woff2" crossorigin>${['home','directory','404'].includes(page)?'<link rel="modulepreload" href="/js/vendor/three-scene.js">':''}<link rel="stylesheet" href="/css/main.css"><link rel="stylesheet" href="/css/pages.css"><link rel="stylesheet" href="/css/wordmark.css"><link rel="stylesheet" href="/css/video.css">${page==='project'?'<link rel="stylesheet" href="/css/'+(slug==='trajetoria'?'trajectory':'module-experiences')+'.css">':''}${page==='home'?'<link rel="stylesheet" href="/css/home-intro.css"><link rel="stylesheet" href="/css/science-globe.css"><link rel="stylesheet" href="/css/principle-visuals.css"><link rel="stylesheet" href="/css/tiles.css"><link rel="stylesheet" href="/css/journey-guide.css"><link rel="stylesheet" href="/css/medical-experiences.css">':''}<noscript><style>.hero .hero-fallback{opacity:1;visibility:visible}</style>${page==='home'?'<style>.shared-artwork .hero-fallback{opacity:1;visibility:visible}.home-world .shared-artwork{height:100%}</style>':''}</noscript></head><body data-page="${page==='project'?'module':page}" data-build="${build}">${page==='project'?'':header(page)}<main id="main" data-scroll-container tabindex="-1">${renderContent(page,slug)}${['home','community'].includes(page)?footer():''}</main><dialog class="profile-dialog" aria-label="Percurso THE MED"><div class="modal-content"></div></dialog><div class="dot-cursor" aria-hidden="true"><span></span></div>${page==='project'?'<script type="module" src="/js/'+(slug==='trajetoria'?'trajectory':'module-experiences-controller')+'.js"></script>':''}<script type="module" src="/js/app.js"></script></body></html>`;}
